131	// ---- 账户 ----
132	
133	// RegisterAccount 以唯一编号登记账户，登记后即为可用状态。
134	//
135	// 登记以一次保存完成为准：新账户尚未原子替换原数据就发生保存错误（如数据
136	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功或编号冲突，也
137	// 不能用失败后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法
138	// 读取或解析、状态未能按磁盘重建，同一个仍打开的登记册也必须立即表现为该
139	// 编号从未登记：GetAccount 返回 ErrNotFound，藏品转让不能把它当成已登记的
140	// 接收账户；失败不占用新账户编号，保存条件未恢复时用该编号再次登记仍实际
141	// 尝试保存并返回当次保存错误，而不是因遗留账户返回 ErrAlreadyExists。原
142	// 数据仍可读取的普通保存失败同样撤销本次登记，不依赖重新读取成功。随后另
143	// 一次无关操作成功保存也不会把这个未保存的账户夹带落盘，关闭再打开登记册
144	// 后它仍不存在。读写恢复后用该编号重新登记，以本次提交的元数据为准，保存
145	// 成功才显示为可用账户。此前成功登记的账户及其元数据、可用或停用状态，以及
146	// 已有藏品的持有人、版本与历史都原样保留。空白编号仍返回 ErrInvalidArgument，
147	// 元数据允许为空；已成功登记的编号无论账户是否停用都返回 ErrAlreadyExists、
148	// 不覆盖其记录，这些业务拒绝不因数据位置恰好不可写而变成保存错误。
149	func (r *Registry) RegisterAccount(id, metadata string) error {
150		r.mu.Lock()
151		defer r.mu.Unlock()
152		if err := r.checkOpen(); err != nil {
153			return err
154		}
155		if strings.TrimSpace(id) == "" {
156			return fmt.Errorf("%w: 账户编号不能为空", ErrInvalidArgument)
157		}
158		if _, ok := r.state.Accounts[id]; ok {
159			return fmt.Errorf("%w: 账户 %s", ErrAlreadyExists, id)
160		}
161		r.state.Accounts[id] = account{ID: id, Metadata: metadata, Active: true}
162		if err := r.commit(); err != nil {
163			// commit 失败时已尝试按磁盘内容重建状态：重建成功则新账户已随旧
164			// 状态整体消失，删除是无害的兜底；磁盘暂时不可读、状态未能重建时
165			// 新账户仍在，显式删除，让当前仍打开的登记册表现为该编号从未登记
166			// ——GetAccount 返回 ErrNotFound、转让不把它当成已登记的接收账户、
167			// 再次登记不会撞上遗留的 ErrAlreadyExists，也不被随后另一次成功
168			// 保存夹带落盘。返回实际写入错误，而非成功、编号冲突或重新读取时
169			// 的错误。
170			delete(r.state.Accounts, id)
171			return err
172		}
173		return nil
174	}
175	
176	// DeactivateAccount 停用账户。停用后其原有藏品与历史仍可查询，但不能
177	// 再发行、发起或接收新的转让；停用不影响已经落盘的任何记录。
178	//
179	// 停用以保存成功为准：停用状态尚未原子替换原数据就发生写入错误（如数据
180	// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功，也不能用失败
181	// 后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法读取或解析、
182	// 状态未能按磁盘重建，同一个仍打开的登记册也必须保持停用前的样子：该账户
183	// 仍可用，编号与元数据不变，其已有藏品的持有人、版本与历史原样保留；其他
184	// 账户此前已经成功停用的状态不被恢复为可用。原数据仍可读取的普通保存失败
185	// 同样撤销本次变化，不依赖重新读取成功。随后另一次无关操作成功保存也不会
186	// 把这次未保存的停用夹带落盘。保存条件恢复后该账户仍按原有规则参与转让；
187	// 之后再次提交停用须重新完成保存，成功返回后才显示不可用，并按现有规则
188	// 拒绝其发起或接收新的转让。
189	func (r *Registry) DeactivateAccount(id string) error {
190		r.mu.Lock()
191		defer r.mu.Unlock()
192		if err := r.checkOpen(); err != nil {
193			return err
194		}
195		a, ok := r.state.Accounts[id]
196		if !ok {
197			return fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
198		}
199		if !a.Active {
200			return nil // 停用是幂等的终态，已停用直接成功，不要求再次写入
201		}
202		// 保存停用前的账户记录：停用以一次保存完成为准。commit 失败且磁盘
203		// 暂时不可读、状态未能按磁盘重建时据此显式撤销，否则这次未保存的停用
204		// 会留在当前已打开的登记册中（GetAccount 显示不可用、转让被按停用
205		// 拒绝），并被随后另一次成功保存夹带落盘。
206		prev := a
207		a.Active = false
208		r.state.Accounts[id] = a
209		if err := r.commit(); err != nil {
210			// commit 失败时已尝试按磁盘内容重建状态：重建成功则账户已随旧状态
211			// 整体恢复可用，写回的记录与磁盘一致；磁盘暂时不可读、状态未能重建
212			// 时本次停用仍在，显式恢复为停用前记录，藏品持有、版本与历史本就未
213			// 被触碰。返回实际写入错误，而非成功或重新读取时的错误。
214			r.state.Accounts[id] = prev
215			return err
216		}
217		return nil
218	}
219	
220	// GetAccount 查询账户；账户不存在时返回包裹 ErrNotFound 的错误。
221	func (r *Registry) GetAccount(id string) (Account, error) {
222		r.mu.Lock()
223		defer r.mu.Unlock()
224		if err := r.checkOpen(); err != nil {
225			return Account{}, err
226		}
227		a, ok := r.state.Accounts[id]
228		if !ok {
229			return Account{}, fmt.Errorf("%w: 账户 %s", ErrNotFound, id)
230		}
231		return Account{ID: a.ID, Metadata: a.Metadata, Active: a.Active}, nil
232	}
