1159	func proxyTransferParamsSig(req ProxyTransferRequest) string {
1160		b, _ := json.Marshal(struct {
1161			Kind   string `json:"kind"`
1162			AuthID string `json:"auth_id"`
1163			Reason string `json:"reason"`
1164		}{"proxy_transfer", req.AuthID, req.Reason})
1165		return string(b)
1166	}
1167	
1168	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
1169	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
1170	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
1171	// 操作者记为实际受托账户并可通过授权编号追溯。
1172	//
1173	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
1174	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
1175	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
1176	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
1177	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
1178	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
1179	//
1180	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
1181	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
1182	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
1183	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1184	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1185	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1186	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1187	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1188	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1189	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1190	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1191	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1192	// 或引用不存在沿用原错误且不占用请求号。
1193	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1194		missing := []string{}
1195		if strings.TrimSpace(req.Operator) == "" {
1196			missing = append(missing, "operator")
1197		}
1198		if strings.TrimSpace(req.Reason) == "" {
1199			missing = append(missing, "reason")
1200		}
1201		if strings.TrimSpace(req.RequestID) == "" {
1202			missing = append(missing, "request_id")
1203		}
1204		if strings.TrimSpace(req.AuthID) == "" {
1205			missing = append(missing, "auth_id")
1206		}
1207		if len(missing) > 0 {
1208			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1209				ErrInvalidArgument, strings.Join(missing, ", "))
1210		}
1211		r.mu.Lock()
1212		defer r.mu.Unlock()
1213		if err := r.checkOpen(); err != nil {
1214			return ProxyTransferResult{}, err
1215		}
1216	
1217		now := r.now()
1218		key := requestKey(req.Operator, req.RequestID)
1219		sig := proxyTransferParamsSig(req)
1220		if prev, ok := r.state.Requests[key]; ok {
1221			return r.replayProxyTransfer(prev, sig)
1222		}
1223	
1224		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1225			if !isValidationErr(bizErr) {
1226				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1227				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1228				r.state.Requests[key] = request{
1229					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1230					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1231				}
1232				if err := r.commit(); err != nil {
1233					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1234					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1235					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1236					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1237					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1238					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1239					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1240					// 回放、结果中业务错误为空，error 保留实际写入错误。
1241					delete(r.state.Requests, key)
1242					return ProxyTransferResult{}, err
1243				}
1244			}
1245			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1246			// 授权状态或授权变更记录。
1247			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1248		}
1249	
1250		a := r.state.Authzs[req.AuthID]
1251		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1252		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1253		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1254		// 追溯。
1255		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1256		a.Status = "used"
1257		a.UsedTxSeq = out.seq
1258		a.UsedAt = now
1259		r.state.Authzs[a.ID] = a
1260		authSeq := r.state.NextAuthSeq + 1
1261		r.state.NextAuthSeq = authSeq
1262		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1263			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1264			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1265			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1266		})
1267		r.state.Requests[key] = request{
1268			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1269			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1270			Version: out.toVer(), TxSeq: out.seq,
1271		}
1272		if err := r.commit(); err != nil {
1273			return ProxyTransferResult{}, err
1274		}
1275		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1276			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1277			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1278			Remainder: out.royalty.Remainder}, nil
1279	}
1280	
1281	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1282		a, ok := r.state.Authzs[req.AuthID]
1283		if !ok {
1284			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1285		}
1286		op, ok := r.state.Accounts[req.Operator]
1287		if !ok {
1288			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1289		}
1290		granter, gOk := r.state.Accounts[a.GranterID]
1291		to, tOk := r.state.Accounts[a.ToID]
1292		if req.Operator != a.TrusteeID {
1293			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1294				ErrForbidden, req.Operator, req.AuthID)
1295		}
1296		if !gOk {
1297			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1298		}
1299		if !tOk {
1300			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1301		}
1302		if !op.Active {
1303			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1304		}
1305		if !granter.Active {
1306			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1307		}
1308		if !to.Active {
1309			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1310		}
1311		switch authzCurrentStatus(a, now) {
1312		case AuthRevoked:
1313			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1314		case AuthExpired:
1315			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1316		case AuthUsed:
1317			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1318		}
1319		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1320		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1321		h, ok := r.state.Holdings[a.ItemID]
1322		if !ok {
1323			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1324		}
1325		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1326			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1327				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1328		}
1329		return nil
1330	}
1331	
1332	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1333		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1334			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1335				ErrRequestConflict, prev.Operator, prev.RequestID)
1336		}
1337		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1338			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1339		if prev.Rejected {
1340			res.Err = codeErr(prev.Reason)
1341			return res, res.Err
1342		}
1343		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1344		// 原价款与应付明细，不重复计入。
1345		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1346		return res, nil
1347	}
