10	// 本文件为单件转让补充"成功转让本身保存失败"场景的回归保障。既有的
11	// transfer_save_failure_test.go 覆盖的是状态类业务拒绝的落盘失败；这里覆盖
12	// 的是账户、藏品与持有版本检查全部通过、本次转让的持有换人/历史/版税应付/
13	// 请求结果尚未原子替换原数据就发生写入失败的情形——这样的转让实际没有保存，
14	// 绝不能成为登记册认可的交易，即使原数据在失败后暂时无法读取或解析。
15	//
16	// 失败返回必须保留实际写入错误并给出空结果（不携带藏品编号、前后持有人、
17	// 版本、历史序号、价款、应付或余款，业务错误为空，不标回放）。同一个仍
18	// 打开的登记册上：藏品继续属于提交前持有人、版本不增加、持有列表与藏品
19	// 历史保持原状、版税查询没有本次计算记录、收款账户不多出应付，请求号与
20	// 历史序号都不被消耗；失败前已有的成功转让、应付与其他藏品记录原样保留。
21	// 读写恢复后，即使用户先做一次无关操作成功保存，也不能把这笔未保存的转让
22	// 一并写入；用原请求重提按当时状态重新判断，条件仍满足时完整完成一次（版本
23	// 只加一次、序号紧接已有历史、按既定系列规则算金额、不标回放），只有此次
24	// 成功保存后再提才回放；恢复期间藏品被另一笔合法转让转出的，原请求按现有
25	// 版本冲突规则拒绝，不能回放先前未保存的成功。
26	//
27	// 失败注入与其他场景共用：在 .registry.json.tmp 上预建目录，save 在
28	// OpenFile 阶段即以 EISDIR 失败（rename 之前）；部分用例同时把数据文件改写
29	// 为无法解析的内容，覆盖"原数据暂时无法读取、commit 无法按磁盘重建状态"。
30	
31	// seedTransferSuccessWorld 建立一个已经存在成功转让与应付记录的登记册：
32	// setupBatchTransferWorld 发行 i1..i5（历史序号 1..5）后，alice 再发行
33	// i6（s1，序号 6）给 bob，bob 以 10000 分把 i6 转让给 alice（序号 7，
34	// carol 10%=1000、dave 5%=500，余款 8500 归 bob）。因此本文件各用例失败
35	// 发生前最后一条历史序号是 7；未保存转让若执行将占用序号 8。
36	func seedTransferSuccessWorld(t *testing.T, r *Registry) {
37		t.Helper()
38		setupBatchTransferWorld(t, r)
39		if _, err := r.Issue(IssueRequest{
40			Operator: "alice", Reason: "首发", RequestID: "ri-i6",
41			ItemID: "i6", SeriesID: "s1", BatchNo: "b1",
42			Metadata: "元-i6", HolderID: "bob",
43		}); err != nil {
44			t.Fatal(err)
45		}
46		if _, err := r.Transfer(TransferRequest{
47			Operator: "bob", Reason: "先存一笔成功转让", RequestID: "rt-prior", ItemID: "i6",
48			ExpectedOwner: "bob", ExpectedVer: 1, ToID: "alice", Price: 10000,
49		}); err != nil {
50			t.Fatal(err)
51		}
52	}
